{
  "name": "function-hooks",
  "version": "1.0.0",
  "description": "Refuses or rewrites tool calls by policy, and with observation on records hook events as database rows and delivers findings per lineage",
  "author": {
    "name": "Bardia Samiee"
  },
  "types": "./hooks/state.d.ts",
  "userConfig": {
    "observation": {
      "type": "boolean",
      "title": "Observation",
      "description": "Recording of hook events and refused calls as database rows, agent spawns and finding delivery at stop boundaries, and the status line",
      "default": false
    },
    "walkPolicy": {
      "type": "boolean",
      "title": "Walk policy",
      "description": "Refusal of a Bash walker that descends into ~/Library/CloudStorage",
      "default": false
    },
    "editThreshold": {
